import{z as B,x as p,o as t,c as A,q as r,j as n,D as E,d as i,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"旋转卡壳","description":"","frontmatter":{"title":"旋转卡壳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rotating-calipers.md","filePath":"cs/rotating-calipers.md","lastUpdated":1791063341000}'),d={name:"cs/rotating-calipers.md"};function h(C,a,m,u,D,f){const l=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="旋转卡壳" tabindex="-1">旋转卡壳 <a class="header-anchor" href="#旋转卡壳" aria-label="Permalink to &quot;旋转卡壳&quot;">​</a></h1><div class="epigraph"><p>凸包上一对对踵点随边旋转；直径、最小宽度、凸多边形距离在 $O(n)$ 内扫完。</p><footer>—— 据 Toussaint, Solving Geometric Problems with the Rotating Calipers, 1983；CLRS 第 33 章整理</footer></div><p>上一课<a href="/cs/convex-hull">凸包</a>把平面点集收成逆时针排好的凸多边形，本课直接在包上转。点集直径只落在包上，最远点对常是对踵的一对。缺口是把「两两配对」换成「卡尺贴边、对侧点单调移动」的一次环扫。不重写 Graham；后课扫描线沿用这一直觉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>包上 \\(h\\) 个点朴素两两配对量距离，\\(O(h^2)\\)；即使先凸包，\\(h\\) 仍可到 \\(n\\) 量级。卡壳的观察是：固定边 \\(e\\)，对侧离 \\(e\\) 所在直线最远的点叫对踵点；当 \\(e\\) 换到下一条边时，对踵点只会继续向前挪，不会后退。于是直径就是各边对踵距离的最大值。同一套扫法换判据：把「离直线最远」换成三点有向面积，得最小面积外接矩形；两凸包的最近、最远点对同样能双指针卡出来。</p><p>缺口是单调对踵，不是旋转几何公式课。</p><p><span class="marginnote">常见误区：初学者容易以为卡壳能直接吃一团散点。实际上它必须先跑凸包把输入收成逆时针凸多边形，而且对踵单调性只在凸形上成立——在凹多边形上直接转，指针会来回摆动，答案漏取甚至死循环。</span></p><h3 id="先凸包" tabindex="-1">先凸包 <a class="header-anchor" href="#先凸包" aria-label="Permalink to &quot;先凸包&quot;">​</a></h3><p>输入若只是一团散点，必须先跑上一课的凸包，再在包上扫描，总复杂度由排序的 \\(O(n\\log n)\\) 主导。卡壳的单调性依赖凸性；在凹多边形上直接转，对踵会来回摆动，答案漏取甚至死循环。</p><p><span class="marginnote">Toussaint 1983 综述卡壳。直径也见 Shamos。后课最近点对是分治，对象全体点不是直径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先把顶点按逆时针排成数组，维护两个下标 \\(i,j\\)。固定边 \\((i,i+1)\\) 时，用叉积比较：只要 \\(j+1\\) 比 \\(j\\) 离这条直线更远就把 \\(j\\) 加一，直到不再增；用这对 \\((i,j)\\) 的距离更新答案，再换下一条边。\\(j\\) 一圈最多走 \\(2h\\) 步，均摊后是 \\(O(h)\\)。</p>',12)),(t(),n(o,null,{default:E(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%87%B8%E5%8C%85%22%5D%20--%3E%20CAL%5B%22%E5%AF%B9%E8%B8%B5%E5%8F%8C%E6%8C%87%E9%92%88%22%5D%0A%20%20CAL%20--%3E%20D%5B%22%E7%9B%B4%E5%BE%84%20%2F%20%E5%AE%BD%E5%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"共线边处可能给出两个等距候选，要固定对齐策略（取更远者或都试），否则直径在平手处漏掉。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：正方形就是典型的平手情形——两条相邻边给出同一对对角顶点。若共线等距时随便丢掉一个候选，直径可能取错；固定「取更远者」或「都试一遍」的规则，平手才不会翻车。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：h=1000 的凸包，两两配对要算约 50 万次距离；卡壳一圈里 j 最多走 2000 步、换边 1000 次，总计约 3000 次叉积。两个数量级的差距，全部来自单调性证明了其余点对不必看。")],-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"凸性把对踵变成单调函数：对边 \\(e\\) 而言，对侧顶点到 \\(e\\) 所在直线的距离沿边界先增后减，所以指针不必回头，总步数均摊成 \\(O(h)\\)。它与二重循环的本质差别是证明了其余点对不必看：一端钉在边 \\(i\\) 上，另一端就由单调性钉死为这一个对踵点。物理图像就是卡尺：一脚贴边滑动，另一脚卡住对侧顶点。外接矩形版本里倾角只在换边处变化，\\(O(h)\\) 个候选角里取最小面积。与 SMAWK 无关。",-1)),a[8]||(a[8]=e("p",null,"双指针一圈扫描的循环结构与终止条件：",-1)),(t(),n(o,null,{default:E(()=>[s(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22i%20%E4%BB%8E%E9%A1%B6%E7%82%B9%200%20%E5%BC%80%E5%A7%8B%EF%BC%8C%E9%92%89%E4%BD%8F%E8%BE%B9%20i%2Ci%2B1%22%5D%20--%3E%20A%5B%22j%20%E7%BD%AE%E4%BA%8E%E5%AF%B9%E4%BE%A7%E8%B5%B7%E7%82%B9%22%5D%0A%20%20A%20--%3E%20C%7B%22j%2B1%20%E6%AF%94%20j%20%E7%A6%BB%E8%BF%99%E6%9D%A1%E8%BE%B9%E6%9B%B4%E8%BF%9C%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20J%5B%22j%20%E5%8A%A0%E4%B8%80%22%5D%0A%20%20J%20--%3E%20C%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20U%5B%22%E7%94%A8%20i%2Cj%20%E4%B8%A4%E7%82%B9%E8%B7%9D%E7%A6%BB%E6%9B%B4%E6%96%B0%E7%9B%B4%E5%BE%84%22%5D%0A%20%20U%20--%3E%20N%7B%22%E8%BE%B9%E6%98%AF%E5%90%A6%E5%B7%B2%E6%89%AB%E5%AE%8C%E4%B8%80%E5%9C%88%EF%BC%9F%22%7D%0A%20%20N%20--%3E%7C%22%E5%90%A6%22%7C%20I%5B%22i%20%E5%8A%A0%E4%B8%80%EF%BC%8C%E6%8D%A2%E4%B8%8B%E4%B8%80%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20I%20--%3E%20A%0A%20%20N%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22%E8%BE%93%E5%87%BA%E7%9B%B4%E5%BE%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<p><span class="marginnote">直觉类比：j 就像被卡尺卡住的顶点——边转一格，它只会顺着边界「向前挪或不动」，从不后退。正因为永不回头，一圈下来 j 的总步数被均摊在 h 条边上，复杂度才从平方掉到线性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维直径——单峰论证在球面上失效，要换旋转球面的技术；带权卡壳与动态凸包也不写。后课默认：平面凸多边形的直径、宽度、外接矩形都能 \\(O(n)\\) 卡出来。下一课扫描线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对踵随边单调；直径 \\(O(h)\\)。</li><li>先凸包 \\(O(n\\log n)\\)。</li><li>只对凸多边形。</li><li>出处：Toussaint, 1983。</li></ul>',5))])}const T=B(d,[["render",h]]);export{g as __pageData,T as default};
